function B($s,$x,$y,$w,$h,$f=$WH,$l=$BD,$wt=1){$q=$s.Shapes.AddShape(5,$x,$y,$w,$h);$q.Fill.Solid();$q.Fill.ForeColor.RGB=$f;if($wt-le0){$q.Line.Visible=0}else{$q.Line.Visible=-1;$q.Line.ForeColor.RGB=$l;$q.Line.Weight=[single]$wt};$q}
function Pic($s,$p,$x,$y,$w,$h){if(!(Test-Path $p)){return};$im=[Drawing.Image]::FromFile($p);try{$sc=[Math]::Min($w/$im.Width,$h/$im.Height);$pw=$im.Width*$sc;$ph=$im.Height*$sc}finally{$im.Dispose()};$s.Shapes.AddPicture($p,0,-1,$x+($w-$pw)/2,$y+($h-$ph)/2,$pw,$ph)|Out-Null}
