function Prep($s,$title){foreach($q in @($s.Shapes)){try{if($q.PlaceholderFormat.Type-eq1){$q.TextFrame.TextRange.Text=$title;$q.TextFrame.TextRange.Font.Name="Aptos Display";$q.TextFrame.TextRange.Font.Size=44;$q.TextFrame.TextRange.Font.Bold=-1}elseif($q.PlaceholderFormat.Type-eq7){$q.Delete()}}catch{}}}
